    Bug 1876521 - Do not reject extractFromEmail() on NS_BINDING_ABORTED if content was extracted. r=mkmelin

    This test seems to fail quite often in CCOV tests with

    > JavaScript Error: "Error: 2152398850" {file: "chrome://calendar/content/calendar-extract.js" line: 51}

    which is `NS_BINDING_ABORTED`. I have no clear answer as to why this
    happens, but in the cases I have logged, we actually got the content
    we were looking for and there is no real reason to reject.

    * https://treeherder.mozilla.org/logviewer?job_id=540414640&repo=try-comm-central&task=OxGoLtejQ_-GJpaofFK5Dg.0&lineNumber=3715
    * https://treeherder.mozilla.org/jobs?repo=try-comm-central&revision=ab60af121203bafed87fe595af23d5c57bd403ed

    Differential Revision: https://phabricator.services.mozilla.com/D276809

diff --git a/calendar/base/content/calendar-dnd-listener.js b/calendar/base/content/calendar-dnd-listener.js
index 1e25140954b..bc01f2dc9c5 100644
--- a/calendar/base/content/calendar-dnd-listener.js
+++ b/calendar/base/content/calendar-dnd-listener.js
@@ -66,7 +66,9 @@ var calendarTaskButtonDNDObserver;
           },
           onStartRequest() {},
           onStopRequest(request, statusCode) {
-            if (!Components.isSuccessCode(statusCode)) {
+            // Sometimes we get NS_BINDING_ABORTED here, even though we received
+            // the desired content. Do not reject in these cases.
+            if (!Components.isSuccessCode(statusCode) && !content) {
               reject(new Error(statusCode));
             }
             resolve();
diff --git a/calendar/base/content/calendar-extract.js b/calendar/base/content/calendar-extract.js
index 36b5ba0afc6..012dbae358b 100644
--- a/calendar/base/content/calendar-extract.js
+++ b/calendar/base/content/calendar-extract.js
@@ -46,7 +46,9 @@ var calendarExtract = {
         },
         onStartRequest() {},
         onStopRequest(request, statusCode) {
-          if (!Components.isSuccessCode(statusCode)) {
+          // Sometimes we get NS_BINDING_ABORTED here, even though we received the
+          // desired content. Do not reject in these cases.
+          if (!Components.isSuccessCode(statusCode) && !content) {
             reject(new Error(statusCode));
           }
           resolve();
